/* HEXA BATTLEGROUNDS upgrade3 — PART 15 OF 22. For databases that already ran supabase/upgrade-2 (open world); Run in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-fruit-12', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍌","d":0},{"f":"🍍","d":1},{"f":"🍇","d":9},{"f":"🍎","d":3},{"f":"🍒","d":2},{"f":"🥝","d":8}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍌   🍒   🍇   🥝\n(Banana, Cherry, Grapes, Kiwi)","big":true},"decoder":{"title":"Scramble rule","body":"Subtract each digit from 9."}}'::jsonb, '[{"label":"4-digit vault code","accept":["9701"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍌=0 🍒=2 🍇=9 🥝=8 → 9 minus each digit → 9701', null, 25, 'published'), ('airdrop-fruit-13', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍊","d":2},{"f":"🍉","d":7},{"f":"🥭","d":9},{"f":"🍍","d":5},{"f":"🥝","d":0},{"f":"🍌","d":3}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🥝   🍊   🍉   🍌\n(Kiwi, Orange, Watermelon, Banana)","big":true},"decoder":{"title":"Scramble rule","body":"Add 3 to every digit and keep only the last digit (8 → 1)."}}'::jsonb, '[{"label":"4-digit vault code","accept":["3506"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🥝=0 🍊=2 🍉=7 🍌=3 → +3 to each digit, last digit only → 3506', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); alter table arenas add column if not exists autopilot boolean not null default false; alter table arenas add column if not exists auto_step text; alter table arenas add column if not exists auto_next_at timestamptz; alter table arenas add column if not exists auto_story int not null default -1; alter table arenas add column if not exists auto_length text; create or replace function _auto_preset(p_length text) returns jsonb language sql immutable as $$ select case coalesce(p_length, 'standard') when 'quick' then jsonb_build_object('auto_pacing', 1, 'phase_schedule', '1,3,5,7', 'finale_minute', 9, 'finale_battles', 1, 'zone_warning', 25, 'airdrop_interval', 1, 'red_interval', 2, 'mission_time_pct', 70, 'shuttle_seconds', 12, 'roles_seconds', 12, 'sync_seconds', 90, 'recovery_seconds', 45, 'attack_cooldown', 45, 'protect_seconds', 45, 'boarding_seconds', 12, 'airdrop_window', 90) when 'full' then jsonb_build_object('auto_pacing', 1, 'phase_schedule', '3,15,30,45', 'finale_minute', 55, 'finale_battles', 3, 'zone_warning', 60, 'airdrop_interval', 5, 'red_interval', 6, 'mission_time_pct', 100, 'shuttle_seconds', 20, 'roles_seconds', 15, 'sync_seconds', 0, 'recovery_seconds', 120, 'attack_cooldown', 90, 'protect_seconds', 120, 'boarding_seconds', 25, 'airdrop_window', 180) else jsonb_build_object('auto_pacing', 1, 'phase_schedule', '2,6,11,16', 'finale_minute', 21, 'finale_battles', 2, 'zone_warning', 40, 'airdrop_interval', 3, 'red_interval', 4, 'mission_time_pct', 85, 'shuttle_seconds', 15, 'roles_seconds', 15, 'sync_seconds', 120, 'recovery_seconds', 75, 'attack_cooldown', 60, 'protect_seconds', 75, 'boarding_seconds', 18, 'airdrop_window', 120) end $$; create or replace function _auto_story(p_phase int) returns text[] language sql immutable as $$ select case p_phase when 0 then array['Squad 00: we are already inside', 'Welcome to Operation Siruseri. We have been on this campus longer than you. Find the codes before we find you.'] when 1 then array['Squad 00: supplies are out there', 'We hid supplies across the campus. Search every building. Crates will fall from the sky — be first.'] when 2 then array['Squad 00: duels are live', 'From now on, any squad close to you can challenge you. Trust carefully. Even allies can turn.'] when 3 then array['Squad 00: the circle is closing', 'The safe zone is shrinking toward the centre. Stay inside it, or keep running.'] else array['Squad 00: everyone ends in Room 14', 'Training Room 14 is where this ends. Make your last points count — the finale is coming.'] end $$; create or replace function _auto_finale_minute(p_ev uuid) returns int language plpgsql stable as $$ declare v int; v_s text[]; begin v := coalesce(_cfg(p_ev, 'finale_minute'), 0); if v > 0 then return v; end if; v_s := string_to_array(_cfg_text(p_ev, 'phase_schedule'), ','); begin v := nullif(trim(v_s[array_length(v_s, 1)]), '')::int; exception when others then v := null; end; return coalesce(v, 50) + 5; end $$; create or replace function _auto_fin_pos(p_arena uuid) returns int language plpgsql stable as $$ declare a arenas; v_n int; v_k int; v_rev boolean; v_pos int; begin select * into a from arenas where id = p_arena; v_n := greatest(1, coalesce(_cfg(a.event_id, 'finale_battles'), 2)); if a.results_locked or a.phase in ('results', 'ended') then if not a.winner_revealed then return 5 + v_n; end if; if (select count(*) from arenas x where x.event_id = a.event_id and exists (select 1 from teams where arena_id = x.id and ready)) > 1 and not (select grand_revealed from events where id = a.event_id) then return 6 + v_n; end if; return 7 + v_n; end if; select count(*) into v_k from sync_rounds where arena_id = a.id; v_rev := exists (select 1 from story_events where arena_id = a.id and kind = 'reveal'); v_pos := least(v_k, 2 + v_n); if v_k >= 3 + v_n then return 4 + v_n; end if; if v_rev and v_pos >= 2 + v_n then return 3 + v_n; end if; return v_pos; end $$;
